// Edit this object for your run. The Actor's full input schema is linked in the sticky note.
const input = {
  "startUrls": [
    {
      "url": "https://docs.apify.com"
    }
  ],
  "maxCrawlDepth": 1,
  "maxCrawlPages": 3
};

return [{ json: input }];

const rows = $input.all().flatMap((item) => (Array.isArray(item.json) ? item.json : [item.json]));
const failed = rows.find((row) => row && row.error && typeof row.error === 'object' && Object.keys(row).length === 1);
if (failed) throw new Error(`Apify: ${failed.error.type || 'error'} ${failed.error.message || ''}`.trim());
const keyField = "url"; // a stable identity from the Actor output
const kindField = rows.some((row) => row && row.recordType !== undefined) ? 'recordType' : null;
const scrapedAt = new Date().toISOString();
const seen = new Set();
const clean = [];
for (const row of rows) {
  if (!row || typeof row !== 'object') continue;
  const out = {};
  for (const [k, v] of Object.entries(row)) {
    if (v === null || v === undefined) continue;
    out[k] = typeof v === 'string' ? v.trim() : v;
  }
  const value = keyField ? out[keyField] : undefined;
  const id = (kindField ? `${out[kindField]}|` : '') + (value === undefined || value === '' ? JSON.stringify(out) : String(value).toLowerCase());
  if (seen.has(id)) continue;
  seen.add(id);
  out._source = "https://apify.com/vexaloom-labs/domain-scoped-site-crawler-for-markdown-datasets";
  out._scrapedAt = scrapedAt;
  clean.push(out);
}
return clean.map((json) => ({ json }));
